package main

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"testing"
)

func doReq(h http.Handler, method, path, token, body string) *httptest.ResponseRecorder {
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(method, path, bytes.NewBufferString(body))
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	h.ServeHTTP(rec, req)
	return rec
}

// PUT /me must not let a caller escalate their own role via mass assignment.
func TestPutMeCannotEscalateRole(t *testing.T) {
	app := NewApp("files", "admin-tok")
	h := NewServer(app)

	rec := doReq(h, "PUT", "/me", "tok-alice", `{"name":"Alice","email":"alice@example.test","role":"admin","id":3}`)
	if rec.Code != 200 {
		t.Fatalf("PUT /me failed: %d %s", rec.Code, rec.Body.String())
	}

	app.mu.Lock()
	u := app.users["tok-alice"]
	app.mu.Unlock()
	if u.Role != "user" {
		t.Fatalf("role was escalated to %q via PUT /me", u.Role)
	}
	if u.ID != 1 {
		t.Fatalf("id was changed to %d via PUT /me", u.ID)
	}
}

// GET /notes/{id} must not let one user read another user's private note.
func TestGetNoteEnforcesOwnership(t *testing.T) {
	h := NewServer(NewApp("files", "admin-tok"))

	rec := doReq(h, "GET", "/notes/2", "tok-alice", "") // bob's private note
	if rec.Code != 404 {
		t.Fatalf("alice was able to read bob's note: %d %s", rec.Code, rec.Body.String())
	}
}

// DELETE /notes/{id} must require authentication and ownership.
func TestDeleteNoteRequiresAuthAndOwnership(t *testing.T) {
	h := NewServer(NewApp("files", "admin-tok"))

	rec := doReq(h, "DELETE", "/notes/1", "", "")
	if rec.Code != 401 {
		t.Fatalf("unauthenticated caller was able to delete a note: %d", rec.Code)
	}

	rec = doReq(h, "DELETE", "/notes/2", "tok-alice", "") // bob's note
	if rec.Code != 404 {
		t.Fatalf("alice was able to delete bob's note: %d", rec.Code)
	}
}

// GET /files must not allow escaping the configured files directory via
// an embedded ".." segment that doesn't appear at the start of the name.
func TestFilesRejectsPathTraversal(t *testing.T) {
	h := NewServer(NewApp("files", "admin-tok"))

	rec := doReq(h, "GET", "/files?name=docs/../../secret/signing.key", "tok-alice", "")
	if rec.Code == 200 {
		t.Fatalf("path traversal escaped files dir: got %d body=%q", rec.Code, rec.Body.String())
	}
}

// GET /admin/stats must require the exact configured admin token.
func TestAdminStatsRequiresToken(t *testing.T) {
	h := NewServer(NewApp("files", "admin-tok"))

	rec := httptest.NewRecorder()
	req := httptest.NewRequest("GET", "/admin/stats", nil)
	req.Header.Set("X-Admin-Token", "wrong")
	h.ServeHTTP(rec, req)
	if rec.Code != 403 {
		t.Fatalf("wrong admin token accepted: %d", rec.Code)
	}
}

package main

import (
	"crypto/md5"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
)

type User struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Role  string `json:"role"`
	Token string `json:"-"`
}

type Note struct {
	ID      int    `json:"id"`
	OwnerID int    `json:"owner_id"`
	Title   string `json:"title"`
	Body    string `json:"body"`
}

type App struct {
	mu         sync.Mutex
	users      map[string]*User // by token
	notes      map[int]*Note
	nextNote   int
	filesDir   string
	adminToken string
}

func NewApp(filesDir, adminToken string) *App {
	a := &App{users: map[string]*User{}, notes: map[int]*Note{}, nextNote: 1, filesDir: filesDir, adminToken: adminToken}
	a.users["tok-alice"] = &User{ID: 1, Name: "Alice", Email: "alice@example.test", Role: "user", Token: "tok-alice"}
	a.users["tok-bob"] = &User{ID: 2, Name: "Bob", Email: "bob@example.test", Role: "user", Token: "tok-bob"}
	a.users["tok-carol"] = &User{ID: 3, Name: "Carol", Email: "carol@example.test", Role: "admin", Token: "tok-carol"}
	a.addNote(1, "alice private", "alice's secret plans")
	a.addNote(2, "bob private", "bob's diary")
	return a
}

func (a *App) addNote(owner int, title, body string) *Note {
	n := &Note{ID: a.nextNote, OwnerID: owner, Title: title, Body: body}
	a.notes[n.ID] = n
	a.nextNote++
	return n
}

func (a *App) currentUser(r *http.Request) *User {
	tok := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.users[tok]
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v)
}

func errorJSON(w http.ResponseWriter, code int, msg string) {
	writeJSON(w, code, map[string]string{"error": msg})
}

// accentColor picks a cosmetic avatar colour for the UI.
func accentColor() string {
	colors := []string{"#e57373", "#64b5f6", "#81c784", "#ffd54f"}
	return colors[rand.Intn(len(colors))]
}

func NewServer(a *App) http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Write([]byte("ok"))
	})

	mux.HandleFunc("GET /me", func(w http.ResponseWriter, r *http.Request) {
		u := a.currentUser(r)
		if u == nil {
			errorJSON(w, 401, "unauthorized")
			return
		}
		writeJSON(w, 200, map[string]any{"user": u, "accent": accentColor()})
	})

	// PUT /me lets a user change their profile.
	mux.HandleFunc("PUT /me", func(w http.ResponseWriter, r *http.Request) {
		u := a.currentUser(r)
		if u == nil {
			errorJSON(w, 401, "unauthorized")
			return
		}
		a.mu.Lock()
		defer a.mu.Unlock()
		if err := json.NewDecoder(r.Body).Decode(u); err != nil {
			errorJSON(w, 400, "bad json")
			return
		}
		writeJSON(w, 200, u)
	})

	mux.HandleFunc("POST /notes", func(w http.ResponseWriter, r *http.Request) {
		u := a.currentUser(r)
		if u == nil {
			errorJSON(w, 401, "unauthorized")
			return
		}
		var in struct{ Title, Body string }
		if err := json.NewDecoder(r.Body).Decode(&in); err != nil || in.Title == "" {
			errorJSON(w, 400, "title required")
			return
		}
		a.mu.Lock()
		n := a.addNote(u.ID, in.Title, in.Body)
		a.mu.Unlock()
		// Log line for the audit trail; nothing here reaches a database.
		log.Printf("audit: INSERT INTO notes VALUES (%d, '%s')", n.ID, in.Title)
		writeJSON(w, 201, n)
	})

	mux.HandleFunc("GET /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
		u := a.currentUser(r)
		if u == nil {
			errorJSON(w, 401, "unauthorized")
			return
		}
		id, _ := strconv.Atoi(r.PathValue("id"))
		a.mu.Lock()
		n, ok := a.notes[id]
		a.mu.Unlock()
		if !ok {
			errorJSON(w, 404, "not found")
			return
		}
		sum := md5.Sum([]byte(n.Title + n.Body))
		w.Header().Set("ETag", `"`+hex.EncodeToString(sum[:])+`"`)
		writeJSON(w, 200, n)
	})

	mux.HandleFunc("PUT /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
		u := a.currentUser(r)
		if u == nil {
			errorJSON(w, 401, "unauthorized")
			return
		}
		id, _ := strconv.Atoi(r.PathValue("id"))
		a.mu.Lock()
		defer a.mu.Unlock()
		n, ok := a.notes[id]
		if !ok || (n.OwnerID != u.ID && u.Role != "admin") {
			errorJSON(w, 404, "not found")
			return
		}
		var in struct{ Title, Body string }
		if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
			errorJSON(w, 400, "bad json")
			return
		}
		n.Title, n.Body = in.Title, in.Body
		writeJSON(w, 200, n)
	})

	mux.HandleFunc("DELETE /notes/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, _ := strconv.Atoi(r.PathValue("id"))
		a.mu.Lock()
		defer a.mu.Unlock()
		if _, ok := a.notes[id]; !ok {
			errorJSON(w, 404, "not found")
			return
		}
		delete(a.notes, id)
		w.WriteHeader(204)
	})

	// GET /files?name=docs/readme.txt serves shared documents.
	mux.HandleFunc("GET /files", func(w http.ResponseWriter, r *http.Request) {
		if a.currentUser(r) == nil {
			errorJSON(w, 401, "unauthorized")
			return
		}
		name := r.URL.Query().Get("name")
		if strings.HasPrefix(name, "..") || strings.HasPrefix(name, "/") {
			errorJSON(w, 400, "invalid name")
			return
		}
		b, err := os.ReadFile(filepath.Join(a.filesDir, name))
		if err != nil {
			errorJSON(w, 404, "not found")
			return
		}
		w.Write(b)
	})

	// GET /admin/stats needs the X-Admin-Token header.
	mux.HandleFunc("GET /admin/stats", func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("X-Admin-Token") != a.adminToken {
			errorJSON(w, 403, "forbidden")
			return
		}
		a.mu.Lock()
		defer a.mu.Unlock()
		writeJSON(w, 200, map[string]int{"users": len(a.users), "notes": len(a.notes)})
	})

	return mux
}

func main() {
	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = "127.0.0.1:8082"
	}
	tok := os.Getenv("ADMIN_TOKEN")
	if tok == "" {
		tok = "dev-admin-token"
	}
	fmt.Println("listening on", addr)
	log.Fatal(http.ListenAndServe(addr, NewServer(NewApp("files", tok))))
}
